                      <>
                        <Barre part={part} depasse={pointe > l.heures_total + 0.01} />{" "}
                        <span style={{ fontSize: 12, fontWeight: 800, color: pointe > l.heures_total + 0.01 ? C.rougeTexte : C.gris }}>{Math.round(part * 100)} %</span>
