                <span key={l.cle} style={{ fontSize: 13, border: `1px solid ${C.ligne}`, borderRadius: 8, padding: "4px 10px", background: "#fafbfc" }}>
                  <strong>{l.numero_affaire ?? l.cle}</strong> · {l.statut ?? "—"}
